#!/usr/bin/env bash
set -euo pipefail

# Extract NL-domain triplet sub-corpora from v1.1 triplet corpus.
# Requires: manifests generated by redistribute_manifest_v1.4.sh

manifest_timestamp="${1:?Usage: $0 <manifest_timestamp>}"
query_types=(ate cate jate)

log_dir="./data_generation/generated_datasets/v1.4/.logs"
mkdir -p "${log_dir}"

timestamp=$(date +%Y%m%d_%H%M%S)

echo "=== v1.4 NL Sub-Corpus Extraction ==="
echo "Manifest timestamp: ${manifest_timestamp}"

python3 -m data_generation.redistribute_nl_subcorpus \
    --manifest_timestamp "${manifest_timestamp}" \
    --query_types "${query_types[@]}" \
    2>&1 | tee "${log_dir}/${timestamp}-nl-subcorpus.log"

echo ""
echo "=== NL sub-corpus extraction complete ==="
